"""V2 protocol checks use only generated bytes and isolated, ephemeral servers."""

import asyncio
from dataclasses import replace
import json
from pathlib import Path
import sys
import threading
from types import SimpleNamespace
import unittest
from unittest.mock import patch

from aiohttp import WSMsgType
from aiohttp.test_utils import TestClient, TestServer

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from recognizer import Recognition
from server import FORMAT, SOURCES, Limits, ProtocolError, RUNTIME, Runtime, Session, create_app, error, parse_start


TOKEN = "synthetic_dual_source_test_" + "x" * 40
AUTH = {"Authorization": "Bearer " + TOKEN}
START = {"type": "start", "protocolVersion": 2, **FORMAT, "sources": list(SOURCES)}


def audio(source, pcm=b"\x10\x20" * 1600):
    return bytes([SOURCES[source]]) + pcm


class RecordingRecognizer:
    def __init__(self):
        self.frames = []
        self.responses = []
        self.thread_ids = [threading.get_ident()]
        self.total_bytes = 0
        self.last_end = 0
        self.finished = False

    def accept(self, pcm):
        self.thread_ids.append(threading.get_ident())
        self.frames.append(pcm)
        self.total_bytes += len(pcm)
        result = self.responses.pop(0) if self.responses else Recognition("synthetic partial")
        if isinstance(result, Exception):
            raise result
        if isinstance(result, Recognition) and result.final:
            self.last_end = result.end
        return result

    def finish(self):
        self.thread_ids.append(threading.get_ident())
        self.finished = True
        return Recognition("synthetic tail" if self.frames else "", True,
                           self.last_end, self.total_bytes / 32000)


class StartSchemaTests(unittest.TestCase):
    def test_only_canonical_nonempty_source_subsets_are_valid(self):
        for sources in (["computer"], ["microphone"], ["computer", "microphone"]):
            self.assertEqual(parse_start({**START, "sources": sources}), (2, tuple(sources)))
        for sources in ([], None, "computer", ["speaker"], ["Computer"],
                        ["microphone", "computer"], ["computer", "computer"],
                        ["microphone", "microphone"], ["computer", "microphone", "computer"],
                        [1], [True], [{}], [["computer"]]):
            with self.subTest(sources=sources), self.assertRaises(ProtocolError) as failure:
                parse_start({**START, "sources": sources})
            self.assertEqual(failure.exception.code, "bad_format")

    def test_version_format_and_fields_are_exact(self):
        invalid = [
            {key: value for key, value in START.items() if key != removed}
            for removed in START
        ]
        invalid += [{**START, key: value} for key, value in (
            ("protocolVersion", 1), ("protocolVersion", 3), ("protocolVersion", 2.0),
            ("protocolVersion", True), ("protocolVersion", "2"),
            ("sampleRate", 48000), ("sampleRate", 16000.0), ("channels", True),
            ("channels", 1.0), ("channels", 2), ("encoding", "float32"),
            ("type", "ready"), ("unexpected", 1),
        )]
        for value in invalid:
            with self.subTest(value=value), self.assertRaises(ProtocolError) as failure:
                parse_start(value)
            self.assertEqual(failure.exception.code, "bad_format")
        self.assertEqual(parse_start({"type": "start", **FORMAT}), (1, ("computer",)))

    def test_production_resource_limits_remain_bounded(self):
        limits = Limits()
        self.assertEqual((limits.bytes_per_second, limits.burst_bytes), (32000, 64000))
        self.assertEqual((limits.frames_per_second, limits.burst_frames), (100, 200))
        self.assertEqual((limits.frame_bytes, limits.queue_bytes, limits.queue_frames), (32000, 64000, 32))
        self.assertEqual(limits.session_seconds, 8 * 60 * 60)


class DualProtocolTests(unittest.IsolatedAsyncioTestCase):
    async def asyncSetUp(self):
        self.instances = []

        def factory():
            decoder = RecordingRecognizer()
            self.instances.append(decoder)
            return decoder

        self.app = create_app(TOKEN, factory)
        self.client = TestClient(TestServer(self.app))
        await self.client.start_server()

    async def asyncTearDown(self):
        await self.client.close()

    async def start(self, sources=None):
        sources = list(SOURCES) if sources is None else sources
        ws = await self.client.ws_connect("/v1/transcribe", headers=AUTH)
        await ws.send_json({**START, "sources": sources})
        self.assertEqual(await ws.receive_json(),
                         {**START, "type": "ready", "sources": sources})
        return ws

    async def release(self, ws):
        await ws.close()
        async with asyncio.timeout(2):
            while self.app[RUNTIME].active:
                await asyncio.sleep(0.001)

    async def stop(self, ws):
        await ws.send_json({"type": "stop"})
        events = []
        async with asyncio.timeout(3):
            while True:
                event = await ws.receive_json()
                self.assertNotEqual(event["type"], "error")
                events.append(event)
                if event["type"] == "stopped":
                    return events

    async def test_ready_and_empty_stop_for_both_single_sources_and_dual(self):
        for sources in (["computer"], ["microphone"], list(SOURCES)):
            with self.subTest(sources=sources):
                ws = await self.start(sources)
                events = await self.stop(ws)
                self.assertEqual(events, [
                    {"type": "final", "source": source, "text": "", "segmentId": index,
                     "startSeconds": 0, "endSeconds": 0}
                    for index, source in enumerate(sources, 1)
                ] + [{"type": "stopped"}])
                await self.release(ws)
        self.assertEqual(len(self.instances), 4)
        self.assertEqual(len({id(instance) for instance in self.instances}), 4)

    async def test_independent_pcm_partials_finals_and_one_cpu_thread(self):
        ws = await self.start()
        computer, microphone = self.instances
        comp_pcm, mic_pcm = b"\x12\x34" * 1600, b"\xab\xcd" * 800
        for source, pcm in (("microphone", mic_pcm), ("computer", comp_pcm)):
            await ws.send_bytes(audio(source, pcm))
            self.assertEqual(await ws.receive_json(),
                             {"type": "partial", "source": source, "text": "synthetic partial"})
        computer.responses.append(Recognition("synthetic final", True, 0, 0.2))
        await ws.send_bytes(audio("computer", comp_pcm))
        first_final = await ws.receive_json()
        self.assertEqual(first_final, {
            "type": "final", "source": "computer", "text": "synthetic final",
            "segmentId": 1, "startSeconds": 0, "endSeconds": 0.2,
        })
        # The unchanged mic partial stays suppressed even after the other track finalized.
        await ws.send_bytes(audio("microphone", mic_pcm))
        await ws.send_bytes(audio("computer", comp_pcm))
        self.assertEqual(await ws.receive_json(),
                         {"type": "partial", "source": "computer", "text": "synthetic partial"})
        events = await self.stop(ws)
        self.assertEqual([event["type"] for event in events], ["final", "final", "stopped"])
        self.assertEqual([event["source"] for event in events[:-1]], list(SOURCES))
        self.assertEqual([event["segmentId"] for event in events[:-1]], [2, 3])
        self.assertEqual((events[0]["startSeconds"], events[0]["endSeconds"]), (0.2, 0.3))
        self.assertEqual((events[1]["startSeconds"], events[1]["endSeconds"]), (0, 0.1))
        self.assertEqual(computer.frames, [comp_pcm] * 3)
        self.assertEqual(microphone.frames, [mic_pcm] * 2)
        threads = {ident for decoder in self.instances for ident in decoder.thread_ids}
        self.assertEqual(len(threads), 1)
        self.assertNotIn(threading.get_ident(), threads)

    async def test_global_ids_follow_interleaved_finals_not_source_clocks(self):
        ws = await self.start()
        computer, microphone = self.instances
        computer.responses.append(Recognition("computer fixture", True, 0.2, 0.3))
        microphone.responses.append(Recognition("mic fixture", True, 0.01, 0.02))
        events = []
        for source, size in (("computer", 9600), ("microphone", 3200)):
            await ws.send_bytes(audio(source, b"\0" * size))
            events.append(await ws.receive_json())
        events += (await self.stop(ws))[:-1]
        self.assertEqual([event["segmentId"] for event in events], [1, 2, 3, 4])
        self.assertEqual([event["source"] for event in events],
                         ["computer", "microphone", "computer", "microphone"])
        for source, duration in (("computer", 0.3), ("microphone", 0.1)):
            previous = 0
            for event in events:
                if event["source"] == source:
                    self.assertTrue(previous <= event["startSeconds"] <= event["endSeconds"] <= duration)
                    previous = event["endSeconds"]

    async def test_minimum_and_maximum_wire_frames_preserve_pcm(self):
        for source in SOURCES:
            ws = await self.start([source])
            decoder = self.instances[-1]
            for pcm in (b"\xff\x01", bytes(range(256)) * 125):
                await ws.send_bytes(audio(source, pcm))
            events = await self.stop(ws)
            self.assertEqual(decoder.frames, [b"\xff\x01", bytes(range(256)) * 125])
            self.assertEqual(events[-2]["source"], source)
            self.assertLessEqual(events[-2]["endSeconds"], 32002 / 32000)
            await self.release(ws)

    async def test_rounding_never_exceeds_short_source_duration(self):
        ws = await self.start()
        for source, size in (("computer", 18), ("microphone", 50)):
            await ws.send_bytes(audio(source, b"\0" * size))
            await ws.receive_json()
        events = await self.stop(ws)
        self.assertTrue(0 <= events[0]["endSeconds"] <= 18 / 32000)
        self.assertTrue(0 <= events[1]["endSeconds"] <= 50 / 32000)
        self.assertEqual([event["endSeconds"] for event in events[:-1]], [0.0, 0.001])

    async def test_bad_start_is_rejected_before_either_decoder_exists(self):
        for value in ({**START, "sources": ["computer", "computer"]},
                      {**START, "sources": ["microphone", "computer"]},
                      {**START, "protocolVersion": 2.0},
                      {key: value for key, value in START.items() if key != "sources"}):
            ws = await self.client.ws_connect("/v1/transcribe", headers=AUTH)
            await ws.send_json(value)
            self.assertEqual(await ws.receive_json(), error("bad_format"))
            await self.release(ws)
        self.assertFalse(self.instances)

    async def test_invalid_source_prefix_lengths_and_controls(self):
        for payload in (b"", b"\x01", b"\x02", b"\x00\x00\x00", b"\x03\x00\x00",
                        b"\xff\x00\x00", b"\x01\x00", b"\x02\x00",
                        b"\x01" + b"\0" * 32002, b"\0" * 3200,
                        json.dumps(START), '{"type":"stop","source":"computer"}'):
            with self.subTest(wire_bytes=len(payload)):
                ws = await self.start()
                if isinstance(payload, bytes):
                    await ws.send_bytes(payload)
                else:
                    await ws.send_str(payload)
                self.assertEqual(await ws.receive_json(), error("bad_frame"))
                self.assertFalse(any(decoder.frames for decoder in self.instances))
                await self.release(ws)

    async def test_undeclared_source_faults_in_either_single_source_mode(self):
        for selected, undeclared in (("computer", "microphone"), ("microphone", "computer")):
            ws = await self.start([selected])
            await ws.send_bytes(audio(undeclared))
            self.assertEqual(await ws.receive_json(), error("bad_frame"))
            await self.release(ws)

    async def test_transport_ceiling_remains_bounded_and_compression_disabled(self):
        ws = await self.client.ws_connect("/v1/transcribe", headers=AUTH, compress=15)
        self.assertEqual(ws.compress, 0)
        await ws.send_json(START)
        await ws.receive_json()
        await ws.send_bytes(b"\x01" + b"\0" * 64000)
        message = await ws.receive()
        self.assertEqual((message.type, message.data), (WSMsgType.CLOSE, 1009))

    async def test_v2_and_v1_share_single_admission_slot(self):
        ws = await self.start()
        response = await self.client.get("/v1/transcribe", headers=AUTH)
        self.assertEqual(response.status, 409)
        self.assertEqual(await response.json(), error("busy"))
        await self.stop(ws)
        await self.release(ws)
        legacy = await self.client.ws_connect("/v1/transcribe", headers=AUTH)
        await legacy.send_json({"type": "start", **FORMAT})
        self.assertEqual(await legacy.receive_json(), {"type": "ready", **FORMAT})
        await legacy.send_json({"type": "stop"})
        self.assertEqual(await legacy.receive_json(), {
            "type": "final", "text": "", "segmentId": 1, "startSeconds": 0, "endSeconds": 0,
        })
        self.assertEqual(await legacy.receive_json(), {"type": "stopped"})

    async def test_second_decoder_initialization_failure_never_sends_ready(self):
        def factory():
            if self.instances:
                raise ValueError("private synthetic initialization diagnostic")
            self.instances.append(RecordingRecognizer())
            return self.instances[-1]

        self.app[RUNTIME].factory = factory
        ws = await self.client.ws_connect("/v1/transcribe", headers=AUTH)
        await ws.send_json(START)
        self.assertEqual(await ws.receive_json(), error("decoder_error"))
        self.assertEqual(len(self.instances), 1)
        self.assertEqual((await self.client.get("/health")).status, 503)

    async def test_one_source_exception_faults_session_and_readiness(self):
        ws = await self.start()
        self.instances[1].responses.append(ValueError("private synthetic decoder diagnostic"))
        await ws.send_bytes(audio("microphone"))
        self.assertEqual(await ws.receive_json(), error("decoder_error"))
        await self.release(ws)
        self.assertFalse(any(decoder.finished for decoder in self.instances))
        self.assertEqual((await self.client.get("/health")).status, 503)
        response = await self.client.get("/v1/transcribe", headers=AUTH)
        self.assertEqual(response.status, 503)
        self.assertEqual(await response.json(), error("model_unavailable"))

    async def test_finish_failure_never_sends_stopped_or_silently_drops_source(self):
        ws = await self.start()
        with patch.object(self.instances[1], "finish", side_effect=ValueError("private fixture")):
            await ws.send_json({"type": "stop"})
            first = await ws.receive_json()
            self.assertEqual((first["type"], first["source"], first["segmentId"]), ("final", "computer", 1))
            self.assertEqual(await ws.receive_json(), error("decoder_error"))
        self.assertEqual((await self.client.get("/health")).status, 503)

    async def test_nonfinal_stop_result_is_a_decoder_failure(self):
        ws = await self.start()
        with patch.object(self.instances[0], "finish", return_value=Recognition("fixture")):
            await ws.send_json({"type": "stop"})
            self.assertEqual(await ws.receive_json(), error("decoder_error"))
        self.assertFalse(self.instances[1].finished)
        self.assertEqual((await self.client.get("/health")).status, 503)

    async def test_one_source_timeout_makes_the_whole_runtime_unready(self):
        ws = await self.start()
        release = threading.Event()
        finished = threading.Event()

        def slow_accept(pcm):
            try:
                release.wait(1)
                return Recognition("fixture")
            finally:
                finished.set()

        self.app[RUNTIME].limits = replace(Limits(), operation_seconds=0.03)
        try:
            with patch.object(self.instances[1], "accept", side_effect=slow_accept):
                await ws.send_bytes(audio("microphone"))
                self.assertEqual(await asyncio.wait_for(ws.receive_json(), 2), error("decoder_error"))
                self.assertEqual((await self.client.get("/health")).status, 503)
        finally:
            release.set()
            async with asyncio.timeout(2):
                while not finished.is_set():
                    await asyncio.sleep(0.001)

    async def test_invalid_decoder_results_fail_unready_with_safe_error(self):
        results = (None, Recognition("x" * 8193), Recognition("fixture", True, 0, 0.10001),
                   Recognition("fixture", True, -0.01, 0), Recognition("fixture", True, 0.1, 0.01),
                   Recognition("fixture", True, 0, float("nan")),
                   Recognition("fixture", True, 0, float("inf")),
                   Recognition("fixture", True, 0, 10 ** 400),
                   Recognition("fixture", True, 0, "private fixture"))
        for result in results:
            app = create_app(TOKEN, RecordingRecognizer)
            async with TestClient(TestServer(app)) as client:
                with patch.object(RecordingRecognizer, "accept", return_value=result):
                    ws = await client.ws_connect("/v1/transcribe", headers=AUTH)
                    await ws.send_json(START)
                    await ws.receive_json()
                    await ws.send_bytes(audio("microphone"))
                    self.assertEqual(await ws.receive_json(), error("decoder_error"))
                    self.assertEqual((await client.get("/health")).status, 503)
                    await ws.close()

    async def test_same_source_timestamp_regression_is_rejected(self):
        ws = await self.start(["microphone"])
        self.instances[0].responses.extend([
            Recognition("fixture", True, 0, 0.1), Recognition("fixture", True, 0.09, 0.2),
        ])
        await ws.send_bytes(audio("microphone"))
        self.assertEqual((await ws.receive_json())["segmentId"], 1)
        await ws.send_bytes(audio("microphone"))
        self.assertEqual(await ws.receive_json(), error("decoder_error"))
        self.assertEqual((await self.client.get("/health")).status, 503)


class MemorySocket:
    def __init__(self, messages):
        self.messages = asyncio.Queue()
        for message in messages:
            self.messages.put_nowait(SimpleNamespace(
                type=WSMsgType.BINARY if isinstance(message, bytes) else WSMsgType.TEXT, data=message))
        self.sent = []

    async def receive(self):
        return await self.messages.get()

    async def send_json(self, value):
        self.sent.append(value)


class SourceLimitTests(unittest.IsolatedAsyncioTestCase):
    async def asyncSetUp(self):
        self.runtime = Runtime(TOKEN, RecordingRecognizer, Limits())

    async def asyncTearDown(self):
        self.runtime.executor.shutdown(wait=True, cancel_futures=True)

    def session(self, messages, sources=None, limits=None):
        self.runtime.limits = limits or Limits()
        sources = list(SOURCES) if sources is None else sources
        return Session(self.runtime, MemorySocket(messages),
                       {source: RecordingRecognizer() for source in sources}, 2)

    async def assert_fault(self, session, code):
        with self.assertRaises(ProtocolError) as failure:
            await session.receive()
        self.assertEqual(failure.exception.code, code)

    async def test_byte_rate_and_prefix_accounting_are_per_source(self):
        session = self.session(
            [audio("computer"), audio("microphone"), audio("computer", b"\0\0")],
            limits=replace(Limits(), burst_bytes=3200, bytes_per_second=0))
        await self.assert_fault(session, "rate_limit")
        self.assertEqual(session.queued_bytes, 6400)
        self.assertEqual([state.audio_credit for state in session.sources.values()], [0, 0])
        self.assertEqual([state.total_bytes for state in session.sources.values()], [3200, 3200])

    async def test_frame_rate_is_per_source_not_per_session(self):
        session = self.session(
            [audio("microphone", b"\0\0"), audio("computer", b"\0\0"), audio("microphone", b"\0\0")],
            limits=replace(Limits(), burst_frames=1, frames_per_second=0))
        await self.assert_fault(session, "rate_limit")
        self.assertEqual(session.queue.qsize(), 2)
        self.assertEqual([state.frame_credit for state in session.sources.values()], [0, 0])

    async def test_refill_elapsed_time_is_independent_for_each_source(self):
        session = self.session([
            audio("computer", b"\0" * 32000), audio("microphone", b"\0" * 32000), '{"type":"stop"}',
        ])
        for state in session.sources.values():
            state.last_receive = 0
            state.audio_credit = state.frame_credit = 0
        with patch("server.time", SimpleNamespace(monotonic=lambda: 1)):
            self.assertTrue(await session.receive())
        self.assertEqual([state.audio_credit for state in session.sources.values()], [0, 0])
        self.assertEqual([state.frame_credit for state in session.sources.values()], [99, 99])
        self.assertEqual([state.last_receive for state in session.sources.values()], [1, 1])

    async def test_full_production_byte_budget_excludes_source_prefixes(self):
        for sources in (["microphone"], list(SOURCES)):
            messages = [audio(source, b"\0" * 32000) for source in sources for _ in range(2)]
            session = self.session(messages + ['{"type":"stop"}'], sources)
            self.assertTrue(await session.receive())
            self.assertEqual(session.queued_bytes, 64000 * len(sources))
            self.assertEqual(session.queue_bytes, 64000 * len(sources))
            self.assertEqual(session.queue.maxsize, 32 * len(sources))
            self.assertEqual([state.total_bytes for state in session.sources.values()], [64000] * len(sources))

    async def test_audio_duration_limit_is_independent(self):
        session = self.session(
            [audio("computer"), audio("microphone"), audio("microphone", b"\0\0")],
            limits=replace(Limits(), session_seconds=0.1))
        await self.assert_fault(session, "session_limit")
        self.assertEqual(session.queue.qsize(), 2)
        self.assertEqual(session.sources["computer"].total_bytes, 3200)

    async def test_queue_pcm_budget_scales_only_with_declared_source_count(self):
        for sources in (["microphone"], list(SOURCES)):
            source = sources[0]
            session = self.session(
                [audio(item, b"\0" * 4) for item in sources] + [audio(source, b"\0" * 4)], sources,
                replace(Limits(), queue_bytes=4))
            await self.assert_fault(session, "backlog")
            self.assertEqual(session.queued_bytes, 4 * len(sources))
            self.assertEqual(session.queue.qsize(), len(sources))

    async def test_queue_frame_cap_scales_only_with_declared_source_count(self):
        for sources in (["computer"], list(SOURCES)):
            source = sources[0]
            session = self.session(
                [audio(item, b"\0\0") for item in sources] + [audio(source, b"\0\0")], sources,
                replace(Limits(), queue_frames=1))
            await self.assert_fault(session, "backlog")
            self.assertEqual(session.queue.qsize(), len(sources))
            self.assertEqual(session.queued_bytes, 2 * len(sources))

    async def test_one_track_cannot_borrow_the_other_track_queue_budget(self):
        session = self.session(
            [audio("computer", b"\0" * 4), audio("computer", b"\0" * 2)],
            limits=replace(Limits(), queue_bytes=4))
        await self.assert_fault(session, "backlog")
        self.assertEqual(session.queued_bytes, 4)
        self.assertEqual(session.sources["computer"].queued_bytes, 4)
        self.assertEqual(session.sources["microphone"].queued_bytes, 0)

    async def test_one_track_cannot_fill_the_other_track_frame_slots(self):
        session = self.session(
            [audio("microphone", b"\0\0"), audio("microphone", b"\0\0")],
            limits=replace(Limits(), queue_frames=1))
        await self.assert_fault(session, "backlog")
        self.assertEqual(session.queue.qsize(), 1)
        self.assertEqual(session.sources["microphone"].queued_frames, 1)
        self.assertEqual(session.sources["computer"].queued_frames, 0)

    async def test_stop_waits_for_full_queue_then_drains_every_track_in_canonical_order(self):
        session = self.session(
            [audio("microphone"), audio("computer"), '{"type":"stop"}'],
            limits=replace(Limits(), queue_frames=1))
        receiver = asyncio.create_task(session.receive())
        worker = None
        try:
            async with asyncio.timeout(2):
                while not session.ws.messages.empty():
                    await asyncio.sleep(0)
            self.assertTrue(session.queue.full())
            self.assertFalse(receiver.done())
            worker = asyncio.create_task(session.recognize())
            self.assertTrue(await asyncio.wait_for(receiver, 2))
            await asyncio.wait_for(worker, 2)
            self.assertEqual(session.queue.qsize(), 0)
            self.assertEqual(session.queued_bytes, 0)
            self.assertTrue(all(state.queued_bytes == 0 and state.queued_frames == 0
                                for state in session.sources.values()))
            self.assertTrue(all(state.decoder.finished for state in session.sources.values()))
            self.assertEqual([event["source"] for event in session.ws.sent[:-1]],
                             ["microphone", "computer", "computer", "microphone"])
            self.assertEqual([event["segmentId"] for event in session.ws.sent if event["type"] == "final"], [1, 2])
            self.assertEqual(session.ws.sent[-1], {"type": "stopped"})
        finally:
            for task in (receiver, worker):
                if task is not None and not task.done():
                    task.cancel()
            await asyncio.gather(*(task for task in (receiver, worker) if task is not None),
                                 return_exceptions=True)


if __name__ == "__main__":
    unittest.main()
